# Glossaire MEDINA — chapitre I40 (myocardites, I40 et I41)
from cardio_1 import a, G

# ---- immunologie
a('CAR',[('C','Coxsackievirus (virus Coxsackie)'),('A','and Adenovirus (et adénovirus)'),('R','Receptor (récepteur)')],'Récepteur commun des virus Coxsackie et des adénovirus',
 '<p>Protéine des jonctions intercellulaires utilisée par les virus Coxsackie B et les adénovirus pour entrer dans le cardiomyocyte ; très exprimée dans le cœur jeune et enflammé.</p>','i40-car')
a('CD3',[('CD','Cluster of Differentiation (classe de différenciation)'),('3','numéro 3')],'Antigène de surface CD3',
 '<p>Marqueur de tous les lymphocytes T, associé au récepteur des lymphocytes T. Au moins 7 lymphocytes T CD3 positifs par mm² définissent l’inflammation myocardique (prise de position ESC 2013).</p>','i40-dallas')
a('CD4',[('CD','Cluster of Differentiation (classe de différenciation)'),('4','numéro 4')],'Antigène de surface CD4',
 '<p>Marqueur des lymphocytes T auxiliaires, qui orchestrent la réponse immunitaire adaptative.</p>')
a('CD8',[('CD','Cluster of Differentiation (classe de différenciation)'),('8','numéro 8')],'Antigène de surface CD8',
 '<p>Marqueur des lymphocytes T cytotoxiques, qui tuent les cellules présentant un antigène viral ou tumoral ; prédominants dans la myocardite de l’immunothérapie.</p>')
a('CD28',[('CD','Cluster of Differentiation (classe de différenciation)'),('28','numéro 28')],'Récepteur de costimulation CD28',
 '<p>Récepteur activateur du lymphocyte T ; se lie à CD80 et CD86. CTLA-4 entre en compétition avec lui pour ces ligands.</p>')
a('CD45',[('CD','Cluster of Differentiation (classe de différenciation)'),('45','numéro 45')],'Antigène commun leucocytaire CD45',
 '<p>Marqueur de l’ensemble des leucocytes ; sert au décompte global de l’infiltrat inflammatoire à la biopsie.</p>','i40-dallas')
a('CD68',[('CD','Cluster of Differentiation (classe de différenciation)'),('68','numéro 68')],'Antigène CD68',
 '<p>Marqueur des macrophages et des monocytes à la biopsie endomyocardique.</p>','i40-dallas')
a('CD80',[('CD','Cluster of Differentiation (classe de différenciation)'),('80','numéro 80')],'Ligand de costimulation CD80',
 '<p>Molécule des cellules présentatrices d’antigène, ligand de CD28 (activation) et de CTLA-4 (inhibition) ; bloquée par l’abatacept.</p>','i40-d-2l')
a('CD86',[('CD','Cluster of Differentiation (classe de différenciation)'),('86','numéro 86')],'Ligand de costimulation CD86',
 '<p>Second ligand de CD28 et de CTLA-4 ; bloqué par l’abatacept.</p>','i40-d-2l')
a('CTLA-4',[('C','Cytotoxic (cytotoxique)'),('T','T- (lymphocyte T)'),('L','Lymphocyte (lymphocyte)'),('A','Associated protein (protéine associée)'),('4','numéro 4')],'Protéine 4 associée aux lymphocytes T cytotoxiques',
 '<p>Point de contrôle immunitaire qui freine l’activation des lymphocytes T dans les ganglions. Cible de l’ipilimumab ; l’abatacept en mime la fonction.</p>','i40-d-2l')
a('PD-1',[('P','Programmed (programmée)'),('D','Death (mort cellulaire)'),('1','protéine 1')],'Récepteur de mort cellulaire programmée 1',
 '<p>Point de contrôle immunitaire exprimé par les lymphocytes T activés ; sa liaison à PD-L1 freine le lymphocyte dans les tissus. Cible du nivolumab et du pembrolizumab.</p>','i40-d-2l')
a('PD-L1',[('P','Programmed (programmée)'),('D','Death (mort cellulaire)'),('L','Ligand'),('1','1')],'Ligand 1 du récepteur de mort cellulaire programmée',
 '<p>Ligand de PD-1 exprimé par les tissus, dont les cardiomyocytes, et par de nombreuses tumeurs. Cible de l’atézolizumab et du durvalumab.</p>')
a('TCR',[('T','T- (lymphocyte T)'),('C','Cell (cellule)'),('R','Receptor (récepteur)')],'Récepteur des lymphocytes T',
 '<p>Récepteur qui reconnaît un peptide présenté par une molécule du complexe majeur d’histocompatibilité ; chaque clone de lymphocytes T a son propre récepteur.</p>')
a('TLR',[('T','Toll-'),('L','Like (de type)'),('R','Receptor (récepteur)')],'Récepteurs de type Toll',
 '<p>Récepteurs de l’immunité innée qui reconnaissent des motifs microbiens, par exemple l’ARN viral, et déclenchent la production d’interférons et de cytokines.</p>')
a('HLA',[('H','Human (humain)'),('L','Leukocyte (leucocytaire)'),('A','Antigen (antigène)')],'Antigènes leucocytaires humains',
 '<p>Molécules du complexe majeur d’histocompatibilité humain, qui présentent les peptides aux lymphocytes T ; certains allèles favorisent l’auto-immunité.</p>')
a('IgE',[('Ig','Immunoglobuline'),('E','de classe E')],'Immunoglobulines E',
 '<p>Anticorps des réactions allergiques et antiparasitaires ; souvent élevées dans la granulomatose éosinophilique avec polyangéite et les parasitoses.</p>')

# ---- entités cliniques
a('EGPA',[('E','Eosinophilic (éosinophilique)'),('G','Granulomatosis (granulomatose)'),('P','with Poly- (avec poly-)'),('A','Angiitis (angéite)')],'Granulomatose éosinophilique avec polyangéite',
 '<p>Vascularite des petits vaisseaux avec asthme tardif, rhinosinusite, hyperéosinophilie et neuropathie ; anciennement syndrome de Churg et Strauss. L’atteinte cardiaque en est la première cause de décès.</p>','i40-eos')
a('DRESS',[('D','Drug (médicamenteuse)'),('R','Reaction (réaction)'),('E','with Eosinophilia (avec éosinophilie)'),('S','and Systemic (et systémiques)'),('S','Symptoms (symptômes)')],'Réaction médicamenteuse avec éosinophilie et symptômes systémiques',
 '<p>Hypersensibilité médicamenteuse grave, 2 à 8 semaines après l’introduction du médicament : éruption, fièvre, éosinophilie, atteinte hépatique, rénale ou cardiaque.</p>','i40-eos')
a('FIP1L1-PDGFRA',[('FIP1L1','FIP1-Like 1 : gène semblable à FIP1, Factor Interacting with PAPOLA and CPSF1 (facteur interagissant avec PAPOLA et CPSF1)'),('PDGFRA','Platelet-Derived Growth Factor Receptor Alpha (récepteur alpha du facteur de croissance dérivé des plaquettes)')],'Gène de fusion FIP1L1-PDGFRA',
 '<p>Fusion par délétion sur le chromosome 4, qui crée une tyrosine kinase constamment active ; cause du syndrome hyperéosinophilique myéloprolifératif, très sensible à l’imatinib.</p>','i40-d-eos')
a('MIS-C',[('M','Multisystem (multisystémique)'),('I','Inflammatory (inflammatoire)'),('S','Syndrome'),('C','in Children (de l’enfant)')],'Syndrome inflammatoire multisystémique de l’enfant',
 '<p>Complication post-infectieuse du SARS-CoV-2, 2 à 6 semaines après l’infection, avec fièvre, atteinte de plusieurs organes et fréquente myocardite.</p>','i40-covid')
a('MIS-A',[('M','Multisystem (multisystémique)'),('I','Inflammatory (inflammatoire)'),('S','Syndrome'),('A','in Adults (de l’adulte)')],'Syndrome inflammatoire multisystémique de l’adulte',
 '<p>Équivalent adulte, plus rare, du syndrome inflammatoire multisystémique pédiatrique après une infection par le SARS-CoV-2.</p>','i40-covid')
a('ECMO',[('E','Extra- (extra-)'),('C','Corporeal (corporelle)'),('M','Membrane (à membrane)'),('O','Oxygenation (oxygénation)')],'Oxygénation extracorporelle par membrane',
 '<p>Circulation extracorporelle temporaire. En configuration veino-artérielle, elle assure le débit cardiaque et l’oxygénation dans le choc cardiogénique réfractaire, dont la myocardite fulminante.</p>','i40-ecmo')
a('IC-OS',[('I','International'),('C','Cardio-'),('O','Oncology (oncologie)'),('S','Society (société)')],'Société internationale de cardio-oncologie',
 '<p>Société savante qui a publié en 2021 des définitions consensuelles des toxicités cardiovasculaires des traitements du cancer, dont la myocardite de l’immunothérapie, reprises par l’ESC 2022.</p>','i40-icos')
a('TPMT',[('T','Thio-'),('P','purine'),('M','S-Méthyl-'),('T','transférase')],'Thiopurine S-méthyltransférase',
 '<p>Enzyme qui inactive l’azathioprine et la 6-mercaptopurine. Une activité faible ou nulle, d’origine génétique, expose à une aplasie médullaire : on la mesure avant le traitement.</p>','i40-d-aza')
a('B57.2',[('B57','code CIM-10 de la maladie de Chagas'),('.2','forme chronique avec atteinte cardiaque')],'Code CIM-10 de la maladie de Chagas chronique avec atteinte cardiaque',
 '<p>Code étiologique associé au code I41.2 (myocardite au cours d’une maladie infectieuse ou parasitaire classée ailleurs).</p>','i40-chagas-stades')

# ---- aide-mémoire et essais
a('BACH',[('B','Bloc auriculoventriculaire de haut degré'),('A','Arythmie ventriculaire'),('C','Choc ou insuffisance cardiaque rapidement progressive'),('H','Histoire auto-immune ou Hyperéosinophilie')],'Aide-mémoire des drapeaux rouges d’une myocardite spécifique',
 '<p>Aide pédagogique, non critère officiel : un seul signal fait discuter la biopsie endomyocardique en centre expert.</p>','i40-mnemo-bach')
a('TIMIC',[('T','Tailored (adaptée)'),('IM','IMmunosuppression (immunosuppression)'),('I','in Inflammatory (dans la cardiomyopathie inflammatoire)'),('C','Cardiomyopathy (cardiomyopathie)')],'Essai TIMIC (2009)',
 '<p>Essai randomisé : prednisone et azathioprine pendant 6 mois contre placebo dans la cardiomyopathie inflammatoire virus négative prouvée par biopsie ; amélioration de la FEVG.</p>','i40-cmi')
a('IMAC',[('I','Intervention'),('M','in Myocarditis (dans la myocardite)'),('A','and Acute (et aiguë)'),('C','Cardiomyopathy (cardiomyopathie)')],'Essai IMAC (2001)',
 '<p>Essai randomisé des immunoglobulines intraveineuses chez l’adulte avec cardiomyopathie ou myocardite récente : pas de bénéfice sur la FEVG.</p>')
a('BENEFIT',[('BEN','BENznidazole'),('E','Evaluation (évaluation)'),('F','For (pour)'),('I','Interrupting (interrompre)'),('T','Trypanosomiasis (la trypanosomiase)')],'Essai BENEFIT (2015)',
 '<p>Essai randomisé du benznidazole dans la cardiomyopathie chagasique établie : baisse de la charge parasitaire, sans réduction de la progression clinique.</p>','i40-d-bnz')
a('MIRRA',[('MIRRA','nom propre de l’essai de phase 3 du mépolizumab dans la granulomatose éosinophilique avec polyangéite, non développé lettre à lettre')],'Essai MIRRA (2017)',
 '<p>Essai randomisé : le mépolizumab 300 mg toutes les 4 semaines augmente la durée de rémission et réduit les corticoïdes dans l’EGPA récidivante ou réfractaire.</p>','i40-d-eos')

# ---- codes CIM-10 cités (I41)
for k,lit,full,d in [
 ('A36.8',[('A36','code CIM-10 de la diphtérie'),('.8','autres formes (dont la myocardite diphtérique)')],'Code CIM-10 de la diphtérie, autres formes','Code étiologique associé à I41.0.'),
 ('A39.5',[('A39','code CIM-10 des infections à méningocoques'),('.5','cardite à méningocoques')],'Code CIM-10 de la cardite à méningocoques','Code étiologique associé à I41.0.'),
 ('B26.8',[('B26','code CIM-10 des oreillons'),('.8','autres complications')],'Code CIM-10 des oreillons avec autres complications','Code étiologique associé à I41.1.'),
 ('B58.8',[('B58','code CIM-10 de la toxoplasmose'),('.8','autres atteintes d’organe')],'Code CIM-10 de la toxoplasmose avec autre atteinte d’organe','Code étiologique associé à I41.2.'),
 ('M05.3',[('M05','code CIM-10 de la polyarthrite rhumatoïde séropositive'),('.3','avec atteinte d’autres organes')],'Code CIM-10 de la polyarthrite rhumatoïde avec atteinte d’autres organes','Code étiologique associé à I41.8.'),
]:
    if k not in G: a(k,lit,full,'<p>'+d+'</p>')
if 'D86.8' not in G:
    a('D86.8',[('D86','code CIM-10 de la sarcoïdose'),('.8','sarcoïdose d’autres localisations et localisations associées')],'Code CIM-10 de la sarcoïdose d’autres localisations','<p>Code étiologique associé à I41.8 dans la sarcoïdose cardiaque.</p>','i42-sarcoid')
if 'CD20' not in G:
    a('CD20',[('CD','Cluster of Differentiation (classe de différenciation)'),('20','numéro 20')],'Antigène CD20','<p>Marqueur des lymphocytes B, cible du rituximab.</p>')
if 'EULAR' not in G:
    a('EULAR',[('EU','EUropean (européenne)'),('L','League (ligue)'),('A','Against (contre)'),('R','Rheumatism (le rhumatisme)')],'Alliance européenne des associations de rhumatologie (anciennement Ligue européenne contre le rhumatisme)','<p>Société savante européenne de rhumatologie ; recommandations de 2022 sur les vascularites associées aux ANCA, dont l’EGPA.</p>')
